    return {"id": f"question-social-content-civ-bk-iv-1-{index}", "subject": "social", "type": "single-choice", "prompt": prompt, "options": opts, "knowledgeIds": ["kg-social-content-civ-bk-iv-1"], "difficulty": "medium", "answer": {"value": aid, "explanation": explanation}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0][0], "sourceLocator": "國立卓蘭高中附設國中部公開社會課程計畫；本題只研究公開試題與課程評量的能力結構。", "authoringNote": "依官方課綱、單元 KG、三個公立學校公開來源的題型方向，獨立改寫兒少最佳利益、事實查證、求助通報、受教權、家庭責任、平台與工作安全、支持網絡、表意及風險排序；未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-09", "lessonId": "lesson-social-content-civ-bk-iv-1", "examPatternRefs": refs, "solutionStrategy": "先確認兒少的安全、發展、受教與表意需求，再把事實與推測分開，依風險急迫性、責任角色、證據、隱私與正式支持程序安排處理順序。", "solutionSteps": steps}

